import { Roulette } from './roulette';
import options from './options';
const el = <T extends HTMLElement>(id:string)=>document.getElementById(id) as T;
const totalInput=el<HTMLInputElement>('count'),list=el('kind-list'),add=el<HTMLButtonElement>('add-kind'),summary=el('count-summary');
const map=el<HTMLSelectElement>('map'),rank=el<HTMLInputElement>('rank'),status=el('status');
const start=el<HTMLButtonElement>('start'),shuffle=el<HTMLButtonElement>('shuffle'),reset=el<HTMLButtonElement>('reset');
options.autoRecording=false;options.useSkills=false;
const game=new Roulette();game.setAutoRecording(false);
let running=false,ready=false;
const SETTINGS_KEY='namharu-pinball-settings-v1';
let restoredMap=0;
function saveSettings(){
 if(!ready)return;
 try{localStorage.setItem(SETTINGS_KEY,JSON.stringify({version:1,total:totalInput.value,rows:rows().map(row=>({name:(row.querySelector('.kind-name') as HTMLInputElement).value,count:(row.querySelector('.kind-count') as HTMLInputElement).value})),map:Number(map.value),rank:rank.value,skills:(el('skills') as HTMLInputElement).checked,speed:(el('speed') as HTMLSelectElement).value}));}
 catch{status.textContent='이 브라우저에서 설정을 저장할 수 없습니다.';}
}
function restoreSettings(){
 try{
 const data=JSON.parse(localStorage.getItem(SETTINGS_KEY)||'null');
 if(!data||data.version!==1||typeof data.total!=='string'||typeof data.rank!=='string'||!Array.isArray(data.rows)||!data.rows.length||!data.rows.every((r:any)=>r&&typeof r.name==='string'&&r.name.length<=24&&typeof r.count==='string')||!Number.isInteger(data.map)||data.map<0||typeof data.skills!=='boolean'||!['0.5','1','2'].includes(data.speed))return;
 totalInput.value=data.total;rank.value=data.rank;list.replaceChildren();
 for(const row of data.rows){addRow(row.name,0);(list.lastElementChild!.querySelector('.kind-count') as HTMLInputElement).value=row.count;}
 restoredMap=data.map;(el('skills') as HTMLInputElement).checked=data.skills;options.useSkills=data.skills;(el('speed') as HTMLSelectElement).value=data.speed;game.setSpeed(Number(data.speed));refresh();
 }catch{ /* Ignore unreadable storage and retain the default controls. */ }
}

function rows(){return [...list.querySelectorAll<HTMLElement>('.kind-row')];}
function inputs(){
 const total=Number(totalInput.value);
 if(!Number.isSafeInteger(total)||total<2)throw Error('전체 공 개수는 2 이상의 정수로 입력하세요.');
 const values=rows().map((row,i)=>{
  const name=(row.querySelector('.kind-name') as HTMLInputElement).value.trim();
  const field=row.querySelector('.kind-count') as HTMLInputElement,count=Number(field.value);
  if(!field.value||!Number.isSafeInteger(count)||count<0)throw Error((i+1)+'번째 개수를 0 이상의 정수로 입력하세요.');
  if(count>0&&!name)throw Error((i+1)+'번째 내용을 입력하세요.');
  if(name.length>24)throw Error('내용은 24자까지 입력할 수 있습니다.');
  return{name,count,weight:1};
 }).filter(v=>v.count>0);
 const sum=values.reduce((n,v)=>n+v.count,0);
 if(sum!==total)throw Error(sum<total?'종류별 개수를 '+(total-sum)+'개 더 입력하세요.':'전체 공 개수보다 '+(sum-total)+'개 많습니다.');
 return{values,total};
}
function rankNumber(total:number){const n=Number(rank.value);if(!Number.isInteger(n)||n<1||n>total)throw Error('당첨 순위는 1부터 '+total+'까지 입력하세요.');return n;}
function refresh(edited=false){
 const sum=rows().reduce((n,row)=>n+(Number((row.querySelector('.kind-count') as HTMLInputElement).value)||0),0),total=Number(totalInput.value);
 summary.textContent='입력 '+sum+'개 / 전체 '+(total||0)+'개'+(sum<total?' · 남은 '+(total-sum)+'개':sum>total?' · '+(sum-total)+'개 초과':' · 개수 일치');
 let error='';try{const data=inputs();rankNumber(data.total);}catch(e){error=(e as Error).message;}
 summary.classList.toggle('invalid',!!error);
 start.disabled=shuffle.disabled=!ready||running||!!error;
 add.disabled=running;
 rows().forEach((row,i)=>{(row.querySelector('.kind-name') as HTMLInputElement).setAttribute('aria-label',(i+1)+'번째 내용');(row.querySelector('.kind-count') as HTMLInputElement).setAttribute('aria-label',(i+1)+'번째 개수');(row.querySelector('button') as HTMLButtonElement).disabled=running||rows().length===1;});
 rank.disabled=running;
 if(!running&&ready&&(edited||error))status.textContent=error||'설정 변경됨 · 적용하거나 시작하세요.';
 if(edited)saveSettings();
}
function addRow(name='',count=0){
 const row=document.createElement('div');row.className='kind-row';
 const content=document.createElement('input');content.className='kind-name';content.maxLength=24;content.placeholder='예: 100점';content.value=name;
 const quantity=document.createElement('input');quantity.className='kind-count';quantity.type='number';quantity.min='0';quantity.step='1';quantity.value=String(count);
 const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.setAttribute('aria-label','이 종류 삭제');remove.onclick=()=>{if(running||rows().length===1)return;row.remove();refresh(true);};
 row.append(content,quantity,remove);list.append(row);refresh(true);return content;
}
function lock(on:boolean){running=on;[...list.querySelectorAll('input'),map,totalInput,el('skills')].forEach(e=>(e as HTMLInputElement).disabled=on);reset.disabled=!ready;refresh();}
function prepare(){if(!ready||running)return false;try{const data=inputs(),n=rankNumber(data.total);game.setMarbles(data.values);game.setWinningRank(n-1);rank.max=String(data.total);status.textContent=data.total+'개 준비 · 설정 적용 완료';lock(false);return true;}catch(e){status.textContent=(e as Error).message;refresh();return false;}}
add.onclick=()=>{if(!running){const input=addRow();input.focus();}};
list.addEventListener('input',()=>refresh(true));totalInput.oninput=()=>refresh(true);rank.oninput=()=>refresh(true);
start.onclick=()=>{if(!prepare())return;lock(true);status.textContent='경기 진행 중 · 도착 순서 확인';game.start();};
shuffle.onclick=prepare;
reset.onclick=()=>{game.reset();lock(false);prepare();};
map.onchange=()=>{game.setMap(Number(map.value));prepare();};

el('skills').onchange=()=>{options.useSkills=(el('skills') as HTMLInputElement).checked;};
el('speed').onchange=()=>game.setSpeed(Number((el('speed') as HTMLSelectElement).value));
game.addEventListener('goal',event=>{status.textContent='당첨: '+(event as CustomEvent).detail.winner;lock(false);start.textContent='다시 시작';});
addRow('1번',12);addRow('2번',12);restoreSettings();
document.querySelector('aside')!.addEventListener('change',saveSettings);
const timer=setInterval(()=>{if(!game.isReady)return;clearInterval(timer);el('loading').remove();game.getMaps().forEach((m,i)=>{const o=document.createElement('option');o.value=String(m.index);o.textContent=['회전판 코스','버블 코스','항아리 코스','밤의 코스'][i]||m.title;map.append(o);});if(restoredMap<map.options.length){map.value=String(restoredMap);game.setMap(restoredMap);}
 ready=true;map.disabled=false;prepare();},100);
window.addEventListener('error',()=>{status.textContent='실행 오류가 발생했습니다. 새로고침해 주세요.';});
